import { headers } from 'next/headers'

interface Profile {
  name: string
  email: string
}

async function getProfile(): Promise<Profile> {
  const headersList = await headers()

  // A server-side fetch needs an absolute URL, so rebuild the origin from the
  // incoming request.
  const host = headersList.get('host')
  const protocol = headersList.get('x-forwarded-proto') ?? 'http'

  const res = await fetch(`${protocol}://${host}/api/users/profile`, {
    // Forward the caller's credentials so the endpoint resolves the right user.
    headers: {
      cookie: headersList.get('cookie') ?? '',
      authorization: headersList.get('authorization') ?? '',
    },
    // Per-user data: never store it in the shared server cache.
    cache: 'no-store',
  })

  if (!res.ok) {
    throw new Error(`Failed to fetch user profile: ${res.status}`)
  }

  return res.json()
}

export default async function UserProfile() {
  const profile = await getProfile()

  return (
    <div>
      <h2>Profile</h2>
      <div>{profile.name}</div>
      <div>{profile.email}</div>
    </div>
  )
}

